functions.append_to_cache:
static int append_to_cache(bitwriter_t *w)
{
    if (w->pos > 1024 - 1)
        return -1;
    w->cache[w->pos] = w->byte;
    w->pos++;
    return 0;
}

functions.write_bit:
int write_bit(bitwriter_t *w, _Bool bit)
{
    if (bit)
    {
        w->byte |= 1 << (w->bit_count - 1);
    }
    w->bit_count--;
    if (w->bit_count == 0)
    {
        if (append_to_cache(w) != 0)
            return -1;
        w->byte = 0;
        w->bit_count = 8;
    }
    return 0;
}

functions.write_byte:
int write_byte(bitwriter_t *w, u8 b)
{
    w->byte |= b >> (8 - w->bit_count);
    if (append_to_cache(w) != 0)
        return -1;
    w->byte = b << w->bit_count;
    return 0;
}

functions.write_bits:
int write_bits(bitwriter_t *w, u64 u, int nbits)
{
    if (nbits > 64 || nbits < 0)
        return -1;
    u8 byte = 0;
    u <<= (64 - nbits);
    while (nbits >= 8)
    {
        byte = u >> 56;
        if (write_byte(w, byte) != 0)
            return -1;
        u <<= 8;
        nbits -= 8;
    }
    while (nbits > 0)
    {
        if (write_bit(w, u >> 63) != 0)
            return -2;
        u <<= 1;
        nbits--;
    }
    return 0;
}

functions.write_flush:
int write_flush(bitwriter_t *w, _Bool bit)
{
    while (w->bit_count != 8)
    {
        if (write_bit(w, bit) != 0)
            return -1;
    }
    return 0;
}

