functions.trailing_zero64:
int trailing_zero64(u64 u)
{
    if (u == 0)
        return 64;
    return de_bruijn64_tab[(u & -u) * de_bruijn64 >> (64 - 6)];
}

functions.float_encode_write:
int float_encode_write(float_encoder_t *s, f64 v)
{
    u64 *vp = (u64 *)&v;
    if (s->first)
    {
        s->val = *vp;
        s->first = 0;
        write_bits(&s->w, *vp, 64);
        return 0;
    }
    u64 vdelta = *vp ^ s->val;
    if (vdelta == 0)
    {
        write_bit(&s->w, 0);
    }
    else
    {
        write_bit(&s->w, 1);
    }
    u64 leading = leading_zero64(vdelta);
    u64 trailing = trailing_zero64(vdelta);
    leading &= 0x1F;
    if (leading >= 32)
        leading = 31;
    if (s->leading != ~0 && leading > s->leading && trailing >= s->trailing)
    {
        write_bit(&s->w, 0);
        write_bits(&s->w, vdelta >> s->trailing, 64 - s->leading - s->trailing);
    }
    else
    {
        s->leading = leading;
        s->trailing = trailing;
        write_bit(&s->w, 1);
        write_bits(&s->w, leading, 5);
        u64 sigbits = 64 - leading - trailing;
        write_bits(&s->w, sigbits, 6);
        write_bits(&s->w, vdelta >> trailing, sigbits);
    }
    s->val = *vp;
    return 0;
}

functions.float_encode_flush:
int float_encode_flush(float_encoder_t *s, u8 *dst, u32 *length)
{
    f64 *na = (f64 *)&Nan;
    if (!s->finished)
    {
        s->finished = 1;
        float_encode_write(s, *na);
        write_flush(&s->w, 0);
    }
    *length = s->w.pos + 1;
    memcpy(dst, s->w.cache, s->w.pos + 1);
    return *length;
}

