functions.bit_readbuf:
int bit_readbuf(bitreader_t *br)
{
    u32 i = 0;
    u32 byte_n = 8 - (br->n / 8);
    if (br->len && byte_n > br->len)
    {
        byte_n = br->len;
    }
    if (byte_n == 8)
    {
        br->v = (u64)(br->data[7]) | (u64)(br->data[6]) << 8 | (u64)(br->data[5]) << 16 | (u64)(br->data[4]) << 24 |
                (u64)(br->data[3]) << 32 | (u64)(br->data[2]) << 40 | (u64)(br->data[1]) << 48 |
                (u64)(br->data[0]) << 56;
        br->n = 64;
        br->data = br->data + 8;
        br->len = br->len - 8;
        return 0;
    }
    for (i = 0; i < byte_n; i++)
    {
        br->n += 8;
        br->v |= (u64)(br->data[i]) << (64 - br->n);
    }
    br->data = br->data + byte_n;
    br->len = br->len - byte_n;
    return 0;
}

functions.bitread_reset:
int bitread_reset(bitreader_t *br, u8 *data, u32 len)
{
    br->data = data;
    br->len = len;
    br->n = 0;
    br->v = 0;
    bit_readbuf(br);
    return 0;
}

functions.read_bits:
u64 read_bits(bitreader_t *br, u32 nbits)
{
    u64 v = 0, n = 0;
    if (br->n == 0)
    {
        return ~0;
    }
    if (nbits <= br->n)
    {
        if (nbits == 64)
        {
            v = br->v;
            br->n = 0;
            br->v = 0;
            bit_readbuf(br);
            return v;
        }
        v = br->v >> (64 - nbits);
        br->v = br->v << nbits;
        br->n = br->n - nbits;
        if (br->n == 0)
        {
            bit_readbuf(br);
        }
        return v;
    }
    v = br->v;
    n = br->n;
    br->v = 0;
    br->n = 0;
    bit_readbuf(br);
    v |= (br->v >> n);
    v >>= 64 - nbits;
    u32 buf_n = nbits - n;
    if (buf_n > br->n)
    {
        buf_n = br->n;
    }
    br->v <<= buf_n;
    br->n -= buf_n;
    if (br->n == 0)
    {
        bit_readbuf(br);
    }
    return v;
}

functions.read_bitfast:
_Bool read_bitfast(bitreader_t *br)
{
    _Bool v = ((br->v & ((u64)1 << 63)) != 0);
    br->v <<= 1;
    br->n -= 1;
    return v;
}

functions.read_next:
_Bool read_next(float_decoder_t *s)
{
    u64 v = 0;
    u64 bits, mbits, vbits;
    if (s->finished || s->err)
    {
        return 0;
    }
    if (s->first)
    {
        s->first = 0;
        if (s->val == Nan)
        {
            s->finished = 1;
            return 0;
        }
        return 1;
    }
    _Bool abit;
    if (can_read_bitfast(&s->br))
    {
        abit = read_bitfast(&s->br);
    }
    else if (v = read_bit(&s->br) == ~0)
    {
        s->err = 1;
        return 0;
    }
    else
    {
        abit = v;
    }
    if (abit)
    {
        _Bool bit;
        if (can_read_bitfast(&s->br))
        {
            bit = read_bitfast(&s->br);
        }
        else if (v = read_bit(&s->br) == ~0)
        {
            s->err = 1;
            return 0;
        }
        else
        {
            bit = v;
        }
        if (!bit)
        {
            ;
        }
        else
        {
            bits = read_bits(&s->br, 5);
            if (bits == ~0)
            {
                s->err = 1;
                return 0;
            }
            s->leading = bits;
            bits = read_bits(&s->br, 6);
            if (bits == ~0)
            {
                s->err = 1;
                return 0;
            }
            mbits = bits;
            if (mbits == 0)
            {
                mbits = 64;
            }
            s->trailing = 64 - s->leading - mbits;
        }
        mbits = 64 - s->leading - s->trailing;
        bits = read_bits(&s->br, mbits);
        if (bits == ~0)
        {
            s->err = 1;
            return 0;
        }
        vbits = s->val;
        vbits ^= (bits << s->trailing);
        if (vbits == Nan)
        {
            s->finished = 1;
            return 0;
        }
        s->val = vbits;
    }
    return 1;
}

functions.float_decode_setbytes:
int float_decode_setbytes(float_decoder_t *s, u8 *data, u32 data_len)
{
    memset(s->b, 0, sizeof(s->b));
    memcpy(s->b, data, data_len);
    bitread_reset(&s->br, s->b + 1, data_len - 1);
    u64 v = read_bits(&s->br, 64);
    if (v == ~0)
    {
        return -1;
    }
    s->val = v;
    s->leading = 0;
    s->trailing = 0;
    s->first = 1;
    s->finished = 0;
    s->err = 0;
    return 0;
}

functions.float_decode_block:
int float_decode_block(float_decoder_t *s, u8 *data, u32 len, f64 *res, u32 *res_len)
{
    u32 cnt = 0;
    f64 val = 0.0;
    int ret = float_decode_setbytes(s, data, len);
    if (ret != 0)
    {
        printf("Error\n");
        return ret;
    }
    while (read_next(s))
    {
        val = *(f64 *)(&s->val);
        res[cnt] = val;
        cnt++;
        if (cnt > 20)
        {
            break;
        }
    }
    *res_len = cnt;
    if (s->err)
    {
        printf("Error when decode\n");
        return -1;
    }
    return 0;
}
